// Animation keys follow: ${char.id}_${weaponId}_${direction}${kind} (e.g. dante_katana_nlight, sekiro_spear_nheavy).

const CHAR_FRAME_W = 96;   // frame 96x80 (width 96 so long swords fit)
const CHAR_FRAME_H = 80;
const CHAR_SHEET_COLS = 8;

// true  = use the sprite sheets in assets/chars/ (kyaw.png / thiri.png). If a file is missing or fails to load, the procedural art is used automatically
// false = use only the procedurally drawn art
const USE_SPRITE_SHEETS = true;

// ---------- Attack styles ----------
// Every fighter has their own `moves` (merged on top of the weapon's attack table by moves.js - see that file for all fields).
// sig('heavy', {...}) = the same override for the neutral and the side version of that attack (the signature move).
const sig = (kind, o) => { const r = {}; r[kind + '_n'] = o; r[kind + '_s'] = o; return r; };

