// Base frame index layouts
const BASE_ANIMS = {
  idle:    { frames: [0, 1, 2, 3],             frameRate: 8,  repeat: -1 },
  run:     { frames: [8, 9, 10, 11, 12, 13],   frameRate: 12, repeat: -1 },
  jump:    { frames: [16],                     frameRate: 8,  repeat: 0 },
  fall:    { frames: [17],                     frameRate: 8,  repeat: 0 },
  hurt:    { frames: [18],                     frameRate: 8,  repeat: 0 },
  dodge_n: { frames: [24, 25, 26, 27],         frameRate: 8,  repeat: 0 },
  dodge_s: { frames: [32, 33, 34, 35],         frameRate: 16, repeat: 0 },
};

// Attack frame mappings for procedural / spritesheet frames
const ATTACK_FRAME_MAP = {
  nlight:  [40, 40, 40],
  slight:  [41, 41, 41],
  dlight:  [42, 42, 42],
  ulight:  [43, 43, 43],
  nheavy:  [48, 48, 48, 48],
  sheavy:  [49, 49, 49, 49],
  dheavy:  [50, 50, 50, 50],
  uheavy:  [51, 51, 51, 51],
  // Diagonal (8-direction): ID format ${char}_${weapon}_${dir}_${kind}, e.g. dante_katana_uf_light, sekiro_spear_db_heavy
  // Ground/Air share the same frames (the difference is only in timing/damage). The sheet needs row 8 (frames 56-63)
  uf_light: [56, 56, 56],
  ub_light: [57, 57, 57],
  df_light: [58, 58, 58],
  db_light: [59, 59, 59],
  uf_heavy: [60, 60, 60, 60],
  ub_heavy: [61, 61, 61, 61],
  df_heavy: [62, 62, 62, 62],
  db_heavy: [63, 63, 63, 63],
};

function hexRgb(hex) {
  return { r: (hex >> 16) & 255, g: (hex >> 8) & 255, b: hex & 255 };
}

function fillHex(ctx, hex, a) {
  const c = hexRgb(hex);
  ctx.fillStyle = 'rgba(' + c.r + ',' + c.g + ',' + c.b + ',' + (a == null ? 1 : a) + ')';
}

function roundRect(ctx, x, y, w, h, r) {
  const rr = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + rr, y);
  ctx.arcTo(x + w, y, x + w, y + h, rr);
  ctx.arcTo(x + w, y + h, x, y + h, rr);
  ctx.arcTo(x, y + h, x, y, rr);
  ctx.arcTo(x, y, x + w, y, rr);
  ctx.closePath();
  ctx.fill();
}

// Convert internal attack type (e.g. 'light_s', 'heavy_u_tilt') to weapon anim suffix (e.g. 'slight', 'uheavy')
function attackToSuffix(type) {
  if (!type) return 'nlight';
  const parts = type.split('_');
  const kind = parts[0] || 'light';
  // diagonal: 'light_uf_g' -> 'uf_light' (the _g/_a stance isn't split in animation)
  if (parts[1] && (parts[1] === 'uf' || parts[1] === 'ub' || parts[1] === 'df' || parts[1] === 'db')) {
    return parts[1] + '_' + kind;
  }
  let dir = 'n';
  if (parts[1]) {
    if (parts[1].startsWith('s')) dir = 's';
    else if (parts[1].startsWith('d')) dir = 'd';
    else if (parts[1].startsWith('u')) dir = 'u';
  }
  return dir + kind;
}

function getCharacterAttackAnimKey(p, weaponType) {
  const charId = p.char.id;
  // when unarmed, equippedWeapon is null; previously this searched for "dante_null_nlight" so the animation never changed (an unarmed attack only showed the idle pose)
  const weaponId = weaponType || p.equippedWeapon || 'unarmed';
  // These explicit keys prevent a gun attack from inheriting a sword attack animation.
  if (weaponId === 'gun') return `${charId}_gun_shoot_anim`;
  if (weaponId === 'sword') return `${charId}_sword_slash_anim`;
  const suffix = attackToSuffix(p.attack.type);
  return `${charId}_${weaponId}_${suffix}`;
}

function poseForFrame(i) {
  if (i <= 3) return { name: 'idle', t: i };
  if (i >= 8 && i <= 13) return { name: 'run', t: i - 8 };
  if (i === 16) return { name: 'jump', t: 0 };
  if (i === 17) return { name: 'fall', t: 0 };
  if (i === 18) return { name: 'hurt', t: 0 };
  if (i >= 24 && i <= 27) return { name: 'dodge_n', t: i - 24 };
  if (i >= 32 && i <= 35) return { name: 'dodge_s', t: i - 32 };
  if (i === 40) return { name: 'nlight', t: 0 };
  if (i === 41) return { name: 'slight', t: 0 };
  if (i === 42) return { name: 'dlight', t: 0 };
  if (i === 43) return { name: 'ulight', t: 0 };
  if (i === 48) return { name: 'nheavy', t: 0 };
  if (i === 49) return { name: 'sheavy', t: 0 };
  if (i === 50) return { name: 'dheavy', t: 0 };
  if (i === 51) return { name: 'uheavy', t: 0 };
  const DIAG_NAMES = ['uf_light', 'ub_light', 'df_light', 'db_light', 'uf_heavy', 'ub_heavy', 'df_heavy', 'db_heavy'];
  if (i >= 56 && i <= 63) return { name: DIAG_NAMES[i - 56], t: 0 };
  return { name: 'idle', t: 0 };
}

function drawPlaceholderPose(ctx, ox, oy, w, h, frame, char) {
  const pose = poseForFrame(frame);
  const cx = ox + w / 2;
  const ground = oy + h - 6;
  let bob = 0;
  let lean = 0;
  let stretchX = 1;
  let stretchY = 1;
  let armL = 0, armR = 18, armY = 0;
  let legL = -6, legR = 6, legKick = 0;
  let weap = { x: 16, y: -8, w: 20, h: 5, rot: 0 };

  if (pose.name === 'idle') bob = Math.sin(pose.t * 1.2) * 2;
  if (pose.name === 'run') {
    bob = pose.t % 2 === 0 ? -3 : 1;
    legKick = pose.t % 2 === 0 ? 8 : -8;
    armL = pose.t % 2 === 0 ? 6 : -4;
    armR = pose.t % 2 === 0 ? -4 : 10;
  }
  if (pose.name === 'jump') { bob = -10; armL = -8; armR = 8; armY = -10; }
  if (pose.name === 'fall') { bob = 2; armL = -14; armR = 14; stretchY = 1.08; }
  if (pose.name === 'hurt') { lean = -8; bob = 4; }
  if (pose.name === 'dodge_n') { stretchX = 0.72; stretchY = 1.15; bob = 4; }
  if (pose.name === 'dodge_s') { stretchX = 1.35; stretchY = 0.78; lean = 10; }
  if (pose.name === 'nlight') { armR = 26; weap = { x: 28, y: -4, w: 22, h: 5, rot: 0.15 }; }
  if (pose.name === 'slight') { armR = 32; weap = { x: 34, y: 0, w: 28, h: 5, rot: 0 }; }
  if (pose.name === 'dlight') { armR = 12; weap = { x: 12, y: 18, w: 6, h: 22, rot: 0.1 }; }
  if (pose.name === 'ulight') { armR = 8; weap = { x: 4, y: -28, w: 6, h: 24, rot: -0.1 }; }
  if (pose.name === 'nheavy') { armR = 28; weap = { x: 30, y: -6, w: 26, h: 8, rot: 0.2 }; }
  if (pose.name === 'sheavy') { armR = 36; weap = { x: 38, y: 2, w: 34, h: 8, rot: 0 }; }
  if (pose.name === 'dheavy') { armR = 10; weap = { x: 10, y: 20, w: 10, h: 26, rot: 0.2 }; }
  if (pose.name === 'uheavy') { armR = 6; weap = { x: 2, y: -32, w: 8, h: 28, rot: -0.15 }; }
  // Diagonal poses: the sword is at a 45-degree angle (forward = front, back = behind)
  if (pose.name === 'uf_light')  { armR = 24; weap = { x: 10, y: -8, w: 26, h: 5, rot: -Math.PI / 4 }; }
  if (pose.name === 'ub_light')  { armR = 8;  weap = { x: -10, y: -8, w: 26, h: 5, rot: -3 * Math.PI / 4 }; }
  if (pose.name === 'df_light')  { armR = 24; weap = { x: 10, y: 4, w: 26, h: 5, rot: Math.PI / 4 }; }
  if (pose.name === 'db_light')  { armR = 8;  weap = { x: -10, y: 4, w: 26, h: 5, rot: 3 * Math.PI / 4 }; }
  if (pose.name === 'uf_heavy')  { armR = 28; weap = { x: 10, y: -8, w: 34, h: 8, rot: -Math.PI / 4 }; }
  if (pose.name === 'ub_heavy')  { armR = 8;  weap = { x: -10, y: -8, w: 34, h: 8, rot: -3 * Math.PI / 4 }; }
  if (pose.name === 'df_heavy')  { armR = 28; weap = { x: 10, y: 4, w: 34, h: 8, rot: Math.PI / 4 }; }
  if (pose.name === 'db_heavy')  { armR = 8;  weap = { x: -10, y: 4, w: 34, h: 8, rot: 3 * Math.PI / 4 }; }

  ctx.save();
  ctx.translate(cx + lean, ground - 34 + bob);
  ctx.scale(stretchX, stretchY);

  // Shadow
  fillHex(ctx, 0x000000, 0.25);
  ctx.beginPath();
  ctx.ellipse(0, 34, 16, 4, 0, 0, Math.PI * 2);
  ctx.fill();

  // Legs / Boots
  fillHex(ctx, 0x1f1f24, 1);
  roundRect(ctx, -8 + legL, 14 + Math.max(0, -legKick), 7, 16, 3);
  roundRect(ctx, 1 + legR, 14 + Math.max(0, legKick), 7, 16, 3);

  // Body / Coat / Haori
  fillHex(ctx, char.color, 1);
  roundRect(ctx, -11, -8, 22, 26, 5);

  // Arms
  fillHex(ctx, char.color, 1);
  roundRect(ctx, -14 + armL, -2 + armY, 7, 16, 3);
  roundRect(ctx, 7 + Math.min(armR, 14), -2 + armY, 7, 16, 3);

  // Head & Skin
  fillHex(ctx, 0xffe2c7, 1);
  ctx.beginPath();
  ctx.arc(0, -16, 9, 0, Math.PI * 2);
  ctx.fill();

  // Hair (generic, uses character accent colour)
  fillHex(ctx, char.accent, 1);
  roundRect(ctx, -10, -26, 20, 8, 3);

  // Keep the existing compact chibi sheet style while giving the two fighters
  // different silhouettes in every generated animation frame.
  if (char.visualStyle === 'dante') {
    fillHex(ctx, 0x6f1c2b, 1);
    ctx.beginPath();
    ctx.moveTo(-9, 7); ctx.lineTo(-2, 9); ctx.lineTo(-14, 25); ctx.closePath(); ctx.fill();
    ctx.beginPath();
    ctx.moveTo(9, 7); ctx.lineTo(2, 9); ctx.lineTo(14, 25); ctx.closePath(); ctx.fill();
    fillHex(ctx, 0xf1c64e, 1); ctx.fillRect(-3, 0, 6, 3);
  } else if (char.visualStyle === 'sekiro') {
    fillHex(ctx, 0xb45b42, 1); roundRect(ctx, -5, -9, 17, 4, 2);
    fillHex(ctx, 0x858d91, 1); roundRect(ctx, -15, -1, 6, 12, 2);
    fillHex(ctx, 0xc5a76d, 1); ctx.fillRect(8, -2, 4, 4);
  }

  // Stylized weapon representation
  ctx.save();
  ctx.translate(weap.x, weap.y);
  ctx.rotate(weap.rot);
  fillHex(ctx, 0xb0c4de, 1);
  roundRect(ctx, 0, -weap.h / 2, weap.w, weap.h, 2);
  fillHex(ctx, 0xffffff, 0.9);
  roundRect(ctx, weap.w - 5, -weap.h / 2, 5, weap.h, 2);
  ctx.restore();

  ctx.restore();
}

function generatePlaceholderSheet(scene, char) {
  const w = char.frameWidth || CHAR_FRAME_W;
  const h = char.frameHeight || CHAR_FRAME_H;
  const cols = CHAR_SHEET_COLS;
  const rows = 8; // row 8 (frame 56-63) = diagonal attack frames
  const canvas = document.createElement('canvas');
  canvas.width = w * cols;
  canvas.height = h * rows;
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (let i = 0; i < cols * rows; i++) {
    const col = i % cols;
    const row = Math.floor(i / cols);
    drawPlaceholderPose(ctx, col * w, row * h, w, h, i, char);
  }
  const tmp = char.sheetKey + '__tmp';
  if (scene.textures.exists(tmp)) scene.textures.remove(tmp);
  if (scene.textures.exists(char.sheetKey)) scene.textures.remove(char.sheetKey);
  scene.textures.addCanvas(tmp, canvas);
  scene.textures.addSpriteSheet(char.sheetKey, scene.textures.get(tmp).getSourceImage(), {
    frameWidth: w,
    frameHeight: h,
  });
}

function ensureCharacterSheet(scene, char) {
  const tex = scene.textures.exists(char.sheetKey) ? scene.textures.get(char.sheetKey) : null;
  if (tex && tex.frameTotal > 2) {
    char.hasRealSheet = true;    // a real art sheet is loaded
    return;
  }
  char.hasRealSheet = false;     // file missing / failed to load -> use procedural art
  generatePlaceholderSheet(scene, char);
}

function registerCharacterAnims(scene, char) {
  // 1) Base animations (idle, run, jump, hurt, etc.)
  Object.keys(BASE_ANIMS).forEach((name) => {
    const key = char.id + '_' + name;
    if (scene.anims.exists(key)) scene.anims.remove(key);
    const a = BASE_ANIMS[name];
    scene.anims.create({
      key,
      frames: a.frames.map((f) => ({ key: char.sheetKey, frame: f })),
      frameRate: a.frameRate,
      repeat: a.repeat,
    });
  });

  // 2) Weapon-specific attack animations: ${charId}_${weaponId}_${suffix}
  // Supported pools: designated weapon pool + 'unarmed'
  const weaponsToRegister = [...char.weaponPool, 'unarmed'];
  weaponsToRegister.forEach((wpnId) => {
    Object.keys(ATTACK_FRAME_MAP).forEach((suffix) => {
      const key = `${char.id}_${wpnId}_${suffix}`;
      if (scene.anims.exists(key)) scene.anims.remove(key);
      const frames = ATTACK_FRAME_MAP[suffix];
      scene.anims.create({
        key,
        frames: frames.map((f) => ({ key: char.sheetKey, frame: f })),
        frameRate: suffix.endsWith('heavy') ? 10 : 12,
        repeat: 0,
      });
    });
  });

  // Weapon-specific aliases used by the state machine. The visible poses are drawn
  // procedurally, so these definitions also work when a sheet has no gun art.
  [
    { key: `${char.id}_sword_slash_anim`, frames: [40, 41, 42, 43], frameRate: 24 },
    { key: `${char.id}_gun_shoot_anim`, frames: [40, 41, 40], frameRate: 30 },
  ].forEach((spec) => {
    if (scene.anims.exists(spec.key)) scene.anims.remove(spec.key);
    scene.anims.create({
      key: spec.key,
      frames: spec.frames.map((f) => ({ key: char.sheetKey, frame: f })),
      frameRate: spec.frameRate,
      repeat: 0,
    });
  });
}

function setupCharacters(scene) {
  Object.keys(CHARACTERS).forEach((id) => {
    ensureCharacterSheet(scene, CHARACTERS[id]);
    registerCharacterAnims(scene, CHARACTERS[id]);
  });
  registerWeaponSheetAnims(scene);
}

function registerWeaponSheetAnims(scene) {
  const specs = [
    ['weapon_sword_idle', 'weapon_sheet_sword', [7], 8, -1],
    ['weapon_sword_windup', 'weapon_sheet_sword', [0, 1, 2], 20, 0],
    ['weapon_sword_slash', 'weapon_sheet_sword', [2, 3, 4, 5], 32, 0],
    ['weapon_sword_heavy', 'weapon_sheet_sword', [0, 1, 2, 3, 4, 5], 22, 0],
    ['weapon_sword_recover', 'weapon_sheet_sword', [6, 7], 18, 0],
    ['weapon_gun_idle', 'weapon_sheet_gun', [0, 7], 6, -1],
    ['weapon_gun_aim', 'weapon_sheet_gun', [1], 8, -1],
    ['weapon_gun_fire', 'weapon_sheet_gun', [2, 3, 4], 30, 0],
    ['weapon_gun_recover', 'weapon_sheet_gun', [5, 6, 7], 20, 0],
  ];
  specs.forEach(([key, texture, frames, frameRate, repeat]) => {
    if (!scene.textures.exists(texture)) return;
    if (scene.anims.exists(key)) scene.anims.remove(key);
    scene.anims.create({
      key,
      frames: frames.map((frame) => ({ key: texture, frame })),
      frameRate,
      repeat,
    });
  });
}

function syncWeaponVisual(p) {
  const s = p.weaponVisual;
  if (!s) return;
  const id = p.equippedWeapon;
  if (p.dead || !id || !['sword', 'katana', 'gun'].includes(id)) {
    s.setVisible(false);
    return;
  }
  // In a real art sheet the sword is already in the art -> don't draw it again (only draw the gun)
  if (p.char.hasRealSheet && id !== 'gun') {
    s.setVisible(false);
    return;
  }
  const gun = id === 'gun';
  const data = p.attack.state === 'none' ? null : AttackRouter.getAttackData(p, p.attack.type);
  let key;
  if (gun) {
    key = p.attack.state === 'startup' ? 'weapon_gun_aim' :
      p.attack.state === 'active' ? 'weapon_gun_fire' :
      p.attack.state === 'recovery' ? 'weapon_gun_recover' : 'weapon_gun_idle';
  } else {
    key = p.attack.state === 'startup' ? 'weapon_sword_windup' :
      p.attack.state === 'active' ? (data && data.kind === 'heavy' ? 'weapon_sword_heavy' : 'weapon_sword_slash') :
      p.attack.state === 'recovery' ? 'weapon_sword_recover' : 'weapon_sword_idle';
  }
  const textureKey = gun ? 'weapon_sheet_gun' : 'weapon_sheet_sword';
  if (s.texture.key !== textureKey) s.setTexture(textureKey);
  // The short shinobi blade should stay visually proportionate to Sekiro's body.
  const real = p.char.hasRealSheet;
  // In a real art sheet, the frame center (sprite.y) is at the face (the body is in the lower part of the frame), and the hand is about 15px below.
  // Previously this was computed only for procedural characters, so the gun ended up on the face. Tweak the values here if you want to adjust them.
  const visualScale = real ? 0.6 : (p.char.visualStyle === 'sekiro' ? 0.82 : 1);
  s.setScale(visualScale);
  s.setPosition(p.sprite.x + p.facing * (real ? 24 : 17), p.sprite.y + (real ? 14 : -5));
  s.setFlipX(p.facing < 0);
  s.setVisible(true);
  s.setAlpha(statusAlpha(p));
  const cur = s.anims.currentAnim;
  if ((!cur || cur.key !== key) && s.anims.animationManager.exists(key)) s.play(key, true);
}

// Fade while invulnerable (respawn / dodge). The drawing code uses this
function statusAlpha(p) {
  if (p.spawnHold > 0 || p.spawnInvuln > 0) {
    return (Math.floor((gameScene ? gameScene.time.now : 0) / 100) % 2) ? 0.35 : 0.8;
  }
  if (p.dodge && p.dodge.active && p.dodge.frame <= p.dodge.invuln) return 0.65;
  return 1;
}

function syncCharacterAnim(p) {
  const skin = p.skin;
  if (!p.char || p.dead || !p.sprite.active) {
    if (p.weaponVisual) p.weaponVisual.setVisible(false);
    if (skin) skin.setVisible(false);
    return;
  }
  const body = p.sprite.body;
  const onFloor = body.blocked.down || body.touching.down || (p.dodge.active && !p.dodge.air);

  // Small squash/stretch accent: anticipation, quick active snap, then settle during recovery.
  // (apply to the skin only. Previously scaling the physics sprite changed the hitbox/body size on every attack and jittered on the ground)
  let sx = 1, sy = 1;
  if (p.attack.state === 'startup') {
    const data = AttackRouter.getAttackData(p, p.attack.type);
    const progress = data ? Math.min(1, p.attack.frame / Math.max(1, data.startup)) : 0;
    const squash = Math.sin(progress * Math.PI);
    sx = 1 - 0.13 * squash;
    sy = 1 + 0.13 * squash;
  } else if (p.attack.state === 'active') {
    const data = AttackRouter.getAttackData(p, p.attack.type);
    const progress = data ? Math.min(1, p.attack.frame / Math.max(1, data.active)) : 0;
    const snap = 1 - progress * 0.65;
    sx = 1 + 0.12 * snap;
    sy = 1 - 0.08 * snap;
  } else if (p.attack.state === 'recovery') {
    const data = AttackRouter.getAttackData(p, p.attack.type);
    const progress = data ? Math.min(1, p.attack.frame / Math.max(1, data.recovery)) : 1;
    const settle = 1 - progress;
    sx = 1 - 0.035 * settle;
    sy = 1 + 0.035 * settle;
  }
  const baseScale = p.char.visualScale || 1;

  let targetAnimKey = '';

  if (p.hitstun > 0) {
    targetAnimKey = p.char.id + '_hurt';
  } else if (p.dodge.active) {
    targetAnimKey = p.char.id + '_' + (p.dodge.kind === 'spot' ? 'dodge_n' : 'dodge_s');
  } else if (p.attack.state !== 'none') {
    // Pass the equipped type explicitly: gun always maps to the recoil/muzzle pose.
    targetAnimKey = getCharacterAttackAnimKey(p, p.equippedWeapon);
  } else if (!onFloor) {
    targetAnimKey = p.char.id + '_' + (body.velocity.y < -40 ? 'jump' : 'fall');
  } else if (Math.abs(body.velocity.x) > 40) {
    targetAnimKey = p.char.id + '_run';
  } else {
    targetAnimKey = p.char.id + '_idle';
  }
  p.animKey = targetAnimKey;   // (no longer touches p.state - that is for game logic/audio)

  if (skin) {
    skin.setVisible(true);
    // origin is the feet; the bottom of the physics sprite's frame = bottom of the body
    skin.setPosition(p.sprite.x, p.sprite.y + p.sprite.displayHeight / 2);
    skin.setFlipX(p.facing < 0);
    skin.setScale(baseScale * sx, baseScale * sy);
    skin.setAlpha(statusAlpha(p));
    applySkinTint(p, skin);
    const cur = skin.anims.currentAnim;
    if ((!cur || cur.key !== targetAnimKey) && skin.anims.animationManager.exists(targetAnimKey)) {
      skin.play(targetAnimKey, true);
    }
  }
  syncWeaponVisual(p);
}

// Primitive debug art: visible immediately without loading either character sheet.
function renderProceduralPlayer(p) {
  const g = p.visual;
  if (!g) return;
  g.clear();
  if (p.dead || !p.sprite.active || p.char.hasRealSheet) { g.setVisible(false); return; }
  g.setVisible(true).setPosition(p.sprite.x, p.sprite.y);
  g.setAlpha(statusAlpha(p));

  const weapon = p.equippedWeapon;
  const gun = weapon === 'gun';
  const facing = p.facing || 1;
  const t = (gameScene ? gameScene.time.now : 0) / 1000;
  const onFloor = p.sprite.body.blocked.down || p.sprite.body.touching.down || (p.dodge.active && !p.dodge.air);
  const windup = p.attack.state === 'startup';
  const active = p.attack.state === 'active';
  const heavy = active && AttackRouter.getAttackData(p, p.attack.type).kind === 'heavy';
  const stats = p.char.stats || {};
  const breathRate = stats.idleBreathRate || 8;
  const breathAmount = stats.idleBreathAmount || 1;
  let bob = Math.sin(t * breathRate + (p.startX % 13)) * breathAmount;
  let squashX = 1, squashY = 1;
  if (p.dodge.active) { squashX = p.dodge.kind === 'spot' ? 0.82 : 1.28; squashY = p.dodge.kind === 'spot' ? 1.16 : 0.78; }
  if (Math.abs(p.sprite.body.velocity.x) > 45 && onFloor) bob += Math.abs(Math.sin(t * 18)) * 2.4;
  if (!onFloor) bob -= 2;
  if (p.landAnimFrames > 0) {
    squashX = p.char.visualStyle === 'sekiro' ? 1.22 : 1.12;
    squashY = p.char.visualStyle === 'sekiro' ? 0.72 : 0.84;
  }
  if (windup) { squashX = 0.88; squashY = 1.12; }
  if (active) { squashX = 1.12; squashY = 0.9; }
  g.setScale(squashX, squashY);

  const rectF = (x, y, w, h) => g.fillRect(facing > 0 ? x : -x - w, y, w, h);
  const bodyColor = p.color || 0x48a0d8;
  const hairColor = p.char.accent || 0xffcc66;
  const tucked = !onFloor && p.sprite.body.velocity.y < -40;
  const weaponSheetVisible = !!(p.weaponVisual && p.weaponVisual.visible);

  // Shadow, legs, torso, head, face and free arm.
  g.fillStyle(0x000000, 0.28); g.fillEllipse(0, 29, 34, 7);
  g.fillStyle(0x28313d, 1);
  if (tucked) {
    rectF(-8, 5 + bob, 7, 10); rectF(2, 8 + bob, 7, 10);
  } else {
    rectF(-8, 8 + bob, 7, 17); rectF(2, 8 + bob, 7, 17);
  }
  g.fillStyle(bodyColor, 1); rectF(-11, -12 + bob, 22, 27);
  g.fillStyle(0xffdfc2, 1); g.fillCircle(0, -21 + bob, 10);
  g.fillStyle(hairColor, 1); g.fillRoundedRect(-11, -31 + bob, 22, 8, 3);
  g.fillStyle(0x20242b, 1); g.fillCircle(facing * 4, -22 + bob, 1.4);
  g.fillStyle(bodyColor, 1); rectF(-15, -8 + bob, 6, 15);
  if (p.char.visualStyle === 'dante') {
    // Red coat tails and a gold belt buckle give Dante a different silhouette.
    const coatFlick = Math.sin(t * 13) * (p.attack.state === 'none' ? 1.4 : 2.8);
    g.fillStyle(0x6f1c2b, 1);
    g.fillTriangle(-10, 7 + bob, -2, 9 + bob, -13 - coatFlick, 22 + bob);
    g.fillTriangle(10, 7 + bob, 2, 9 + bob, 13 + coatFlick, 22 + bob);
    g.fillStyle(0xf1c64e, 1); g.fillRect(-3, 1 + bob, 6, 3);
  } else if (p.char.visualStyle === 'sekiro') {
    // Make Sekiro read as a shinobi at game scale: red scarf, layered armor,
    // tied hair, and a clearly metallic prosthetic arm.
    const scarfFidget = Math.sin(t * 3.2) * (p.attack.state === 'none' ? 1.2 : 2.4);
    g.fillStyle(0xa84f3f, 1);
    rectF(-7, -12 + bob, 18, 5);
    g.fillTriangle(facing * -5, -11 + bob, facing * -16 - scarfFidget, -5 + bob, facing * -4, -7 + bob);
    g.fillStyle(0x302d35, 1); rectF(-9, -8 + bob, 17, 16);
    g.fillStyle(0x777276, 1); rectF(-6, -6 + bob, 11, 5);
    g.fillStyle(0xc5a76d, 1); g.fillRect(-1, -5 + bob, 2, 12);
    // Topknot and red headband break up the rounded generic head silhouette.
    g.fillStyle(0x29232a, 1); g.fillEllipse(-1, -34 + bob, 8, 5);
    g.fillStyle(0xa84f3f, 1); g.fillRect(-11, -27 + bob, 22, 2);
    // Prosthetic forearm: steel plates, dark joints and a gold fastening ring.
    g.fillStyle(0x9aa2a6, 1); rectF(-15, -8 + bob, 6, 15);
    g.fillStyle(0xd5d9d7, 1); rectF(-14, -7 + bob, 2, 11);
    g.fillStyle(0x454950, 1); g.fillRect(facing * -12 - 1, -2 + bob, 4, 2);
    g.fillStyle(0xc5a76d, 1); g.fillRect(facing * -10 - 1, 4 + bob, 4, 2);
  }

  const recoil = gun && active ? -facing * 3 : 0;
  if (gun) {
    // Gun: compact black barrel and a visible yellow flash on projectile active frames.
    if (!weaponSheetVisible) {
      g.fillStyle(0x151922, 1);
      rectF(8 + recoil, -8 + bob, 17, 6);
      rectF(11 + recoil, -2 + bob, 5, 8);
      if (active && p.attack.frame <= 1) {
        const mx = facing * (29 + recoil);
        g.fillStyle(0xffdc42, 0.95); g.fillCircle(mx, -5 + bob, 8);
        g.fillStyle(0xffffff, 1); g.fillCircle(mx, -5 + bob, 3.5);
      }
    }
  } else if (weapon) {
    // Sword/katana/spear debug weapon. Wind-up pulls back; active snaps forward.
    let bx = 11, by = -8 + bob, bw = weapon === 'spear' ? 37 : 29;
    if (windup) bx = -18;
    if (active) bx = 19 + Math.min(8, p.attack.frame * 2);
    if (!weaponSheetVisible) {
      g.fillStyle(0x324154, 1); rectF(bx - 3, by - 2, 7, 5);
      g.fillStyle(weapon === 'spear' ? 0xe5bd67 : 0x35a8ff, 1);
      rectF(bx + 2, by - 2, bw, 4);
      g.fillStyle(0xd9f2ff, 1); rectF(bx + bw - 1, by - 1, 5, 2);
    }
    if (active) {
      // White curved slash trail; sampled points keep it compatible with Phaser Graphics.
      const startX = facing * 5, endX = facing * 44;
      const startY = 2 + bob, endY = -22 + bob;
      g.lineStyle(heavy ? 5 : 3, 0xffffff, 0.92);
      g.beginPath();
      for (let i = 0; i <= 10; i++) {
        const q = i / 10, inv = 1 - q;
        const x = inv * inv * startX + 2 * inv * q * facing * 42 + q * q * endX;
        const y = inv * inv * startY + 2 * inv * q * (-29 + bob) + q * q * endY;
        if (i === 0) g.moveTo(x, y); else g.lineTo(x, y);
      }
      g.strokePath();
    }
  } else {
    // Unarmed arm is a distinct warm debug color, never a fake sword animation.
    g.fillStyle(0xf3bc78, 1); rectF(9, -7 + bob, 10, 6);
  }

  // White hit flash (for procedural art)
  if (p.hitFlash > 0) {
    g.fillStyle(0xffffff, 0.7);
    g.fillRoundedRect(-14, -33 + bob, 28, 64, 8);
  }
}
